#!/usr/bin/env node
// Facet token build. Zero dependencies: `node scripts/build.mjs`
// Reads tokens/*.json and writes css/tokens.css, css/typography.css,
// css/materials.css, css/tailwind.css and js/tokens.mjs.
// Never hand-edit the generated files; edit the JSON and rebuild.

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const read = (p) => JSON.parse(readFileSync(join(root, p), 'utf8'));
const write = (p, s) => {
  mkdirSync(dirname(join(root, p)), { recursive: true });
  writeFileSync(join(root, p), s);
  console.log('wrote', p);
};

const prim = read('tokens/primitives.tokens.json');
const type = read('tokens/typography.tokens.json').typography;
const sem = read('tokens/facet.semantic.json');

const HEADER = `/* GENERATED by packages/facet/scripts/build.mjs. Do not edit by hand. */\n`;
const isTok = (o) => o && typeof o === 'object' && '$value' in o;
const ext = (t) => (t.$extensions && t.$extensions.facet) || {};

// ---------- primitives ----------
const light = [], dark = [], p3l = [], p3d = [];
for (const [scale, steps] of Object.entries(prim.color)) {
  for (const [step, t] of Object.entries(steps)) {
    const name = `--ds-${scale}-${step}`;
    light.push(`${name}: ${t.$value};`);
    if (ext(t).dark) dark.push(`${name}: ${ext(t).dark};`);
    if (ext(t).p3) p3l.push(`${name}: ${ext(t).p3};`);
    if (ext(t).p3Dark) p3d.push(`${name}: ${ext(t).p3Dark};`);
  }
}
light.push('--ds-white: #fff;', '--ds-black: #000;');
for (const [k, t] of Object.entries(prim.shadow)) {
  light.push(`--ds-shadow-${k}: ${t.$value};`);
  if (ext(t).dark && ext(t).dark !== t.$value) dark.push(`--ds-shadow-${k}: ${ext(t).dark};`);
}
light.push(
  '--ds-focus-color: var(--ds-blue-700);',
  '--ds-focus-ring: 0 0 0 2px var(--ds-background-100), 0 0 0 4px var(--ds-focus-color);',
  '--ds-focus-ring-outline: 2px solid var(--ds-focus-color);',
  '--ds-focus-border: 0 0 0 1px var(--ds-gray-alpha-600), 0px 0px 0px 4px #00000029;',
  '--ds-overlay-backdrop-color: var(--ds-gray-100);',
  '--ds-overlay-backdrop-opacity: .8;'
);
dark.push('--ds-focus-color: var(--ds-blue-900);', '--ds-focus-border: 0 0 0 1px var(--ds-gray-alpha-600), 0px 0px 0px 4px #ffffff3d;', '--ds-overlay-backdrop-color: var(--ds-background-200);');

// ---------- scalar tokens ----------
const scalars = [];
const ff = prim.font.family;
scalars.push(`--fc-font-sans: ${ff.sans.$value};`, `--fc-font-mono: ${ff.mono.$value};`);
for (const [k, t] of Object.entries(prim.font.weight)) scalars.push(`--fc-weight-${k}: ${t.$value};`);
for (const [k, t] of Object.entries(prim.space)) scalars.push(`--fc-space-${k.replace('.', '_')}: ${t.$value};`);
for (const [k, t] of Object.entries(prim.radius)) scalars.push(`--fc-radius-${k}: ${t.$value};`);
for (const [k, t] of Object.entries(prim.size.control)) scalars.push(`--fc-control-${k}: ${t.$value};`);
for (const [k, t] of Object.entries(prim.size.row)) scalars.push(`--fc-row-${k}: ${t.$value};`);
scalars.push(`--fc-page-width: ${prim.size.page.$value};`, `--fc-page-margin: ${prim.size['page-margin'].$value};`);
for (const [k, t] of Object.entries(prim.z)) scalars.push(`--fc-z-${k}: ${t.$value};`);
for (const [k, t] of Object.entries(prim.motion.easing)) scalars.push(`--fc-ease-${k}: cubic-bezier(${t.$value.join(', ')});`);
for (const [k, t] of Object.entries(prim.motion.duration)) scalars.push(`--fc-duration-${k}: ${t.$value};`);

// ---------- semantic aliases ----------
const alias = (v) =>
  String(v).replace(/\{color\.([a-z-]+)\.(\d+)\}/g, (_, s, n) => `var(--ds-${s}-${n})`);
const semLight = [], semDark = [];
(function walk(node, path) {
  for (const [k, v] of Object.entries(node)) {
    if (k.startsWith('$')) continue;
    const p = [...path, k];
    if (isTok(v)) {
      const name = `--fc-${p.join('-')}`;
      semLight.push(`${name}: ${alias(v.$value)};`);
      if (ext(v).dark) semDark.push(`${name}: ${alias(ext(v).dark)};`);
    } else if (v && typeof v === 'object') walk(v, p);
  }
})(sem, []);

// ---------- nested-theme safety ----------
// Custom properties resolve var() where they are declared, so a dark scope nested inside a light
// page must re-declare every alias that points at a themed primitive. Merge them in.
const keyOf = (l) => l.slice(0, l.indexOf(':'));
const merge = (base, over) => {
  const m = new Map(base.filter((l) => l.includes('var(')).map((l) => [keyOf(l), l]));
  for (const l of over) m.set(keyOf(l), l);
  return [...m.values()];
};
const darkAll = merge([...light, ...semLight], [...dark, ...semDark]);

// ---------- tokens.css ----------
const block = (sel, lines) => `${sel} {\n  ${lines.join('\n  ')}\n}\n`;
const DARK_SEL = '.dark-theme, [data-theme="dark"]';
const AUTO_DARK_SEL = ':root:not(.light-theme):not([data-theme="light"])';
const tokensCss =
  HEADER +
  `/* Facet tokens. Layer 1: Facet primitives (--ds-*), captured verbatim from the vercel.com reference.
   Layer 2: Facet semantics (--fc-*). Theme: light by default, follows the OS, and can be
   forced with class="dark-theme" | "light-theme" or data-theme="dark" | "light" on <html>. */\n\n` +
  block(':root, .light-theme, [data-theme="light"]', ['color-scheme: light;', ...light, ...scalars, ...semLight]) +
  '\n' + block(DARK_SEL, ['color-scheme: dark;', ...darkAll]) +
  `\n@media (prefers-color-scheme: dark) {\n` + block(AUTO_DARK_SEL, ['color-scheme: dark;', ...darkAll]).replace(/^/gm, '  ') + `}\n` +
  `\n/* Wide-gamut (Display P3) upgrades, same as vercel.com. Grays are neutral and need none. */\n` +
  `@media (color-gamut: p3) {\n  @supports (color: oklch(0 0 0)) {\n` +
  block(':root, .light-theme, [data-theme="light"]', p3l).replace(/^/gm, '    ') +
  block(DARK_SEL, p3d).replace(/^/gm, '    ') +
  `  }\n}\n` +
  `@media (color-gamut: p3) and (prefers-color-scheme: dark) {\n  @supports (color: oklch(0 0 0)) {\n` +
  block(AUTO_DARK_SEL, p3d).replace(/^/gm, '    ') +
  `  }\n}\n`;
write('css/tokens.css', tokensCss);

// ---------- typography.css ----------
const resolveFam = (v) => (v.includes('mono') ? 'var(--fc-font-mono)' : 'var(--fc-font-sans)');
let typo = HEADER + `/* Facet type roles. Each class sets size, line-height, weight and tracking together.
   Nest <strong> for the Strong (copy/label) or Subtle (heading) modifier. */\n\n`;
const twUtil = [];
for (const [name, t] of Object.entries(type)) {
  const v = t.$value;
  const body = [
    `font-family: ${resolveFam(v.fontFamily)};`,
    `font-size: ${v.fontSize};`,
    `line-height: ${v.lineHeight};`,
    `font-weight: ${v.fontWeight};`,
    `letter-spacing: ${v.letterSpacing};`,
  ];
  typo += block(`.text-${name}`, body);
  twUtil.push(`@utility text-${name} {\n  ${body.join('\n  ')}\n}`);
  const s = ext(t).strong;
  if (s) {
    const sb = [`font-weight: ${s.fontWeight};`];
    if (s.color) sb.push(`color: ${s.color};`);
    typo += block(`.text-${name} > strong`, sb);
  }
}
typo += `\n/* Numeric helpers. Tabular figures for any column, KPI or value that is compared. */\n` +
  block('.tabular, .fc-num', ['font-variant-numeric: tabular-nums;', 'font-feature-settings: "tnum" 1;']) +
  block('.slashed-zero', ['font-variant-numeric: tabular-nums slashed-zero;']) +
  block('.fc-mono', ['font-family: var(--fc-font-mono);']);
write('css/typography.css', typo);

// ---------- materials.css (exact presets) ----------
const mats = {
  base: ['border', '6px'], small: ['border-small', '6px'], medium: ['border-medium', '12px'], large: ['border-large', '12px'],
  tooltip: ['tooltip', '6px'], menu: ['menu', '12px'], modal: ['modal', '12px'], fullscreen: ['fullscreen', '16px'],
};
let matCss = HEADER + `/* Facet materials: surface (on the page) and floating (above the page). */\n\n`;
for (const [k, [sh, r]] of Object.entries(mats)) {
  matCss += block(`.material-${k}`, ['background-color: var(--ds-background-100);', `box-shadow: var(--ds-shadow-${sh});`, `border-radius: ${r};`]);
}
write('css/materials.css', matCss);

// ---------- tailwind.css (Tailwind v4 theme bridge) ----------
const twColors = [];
for (const [scale, steps] of Object.entries(prim.color)) {
  // Hue allocation (DESIGN.md): purple belongs to gems only, so no bg-purple-* / text-purple-*
  // utilities exist. Gem styling goes through the semantic fc-gem-* utilities instead.
  if (scale === 'purple') continue;
  for (const step of Object.keys(steps)) twColors.push(`--color-${scale}-${step}: var(--ds-${scale}-${step});`);
}
const tw = HEADER + `/* Tailwind CSS v4 bridge. Usage in an app's global CSS:
     @import "tailwindcss";
     @import "@foundingcreative/facet/css/tailwind.css";
   Tailwind's default palette is removed so only Facet steps exist (bg-gray-100, text-gray-900,
   border-gray-400, bg-background-100, text-blue-900 ...), which mirrors how vercel.com itself
   writes classes. */\n
@import "./tokens.css";
@import "./materials.css";

@theme inline {
  --color-*: initial;
  --color-white: var(--ds-white);
  --color-black: var(--ds-black);
  --color-transparent: transparent;
  --color-current: currentColor;
  ${twColors.join('\n  ')}
  --font-sans: var(--fc-font-sans);
  --font-mono: var(--fc-font-mono);
  --radius-xs: 4px;
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --shadow-border: var(--ds-shadow-border);
  --shadow-border-small: var(--ds-shadow-border-small);
  --shadow-border-medium: var(--ds-shadow-border-medium);
  --shadow-border-large: var(--ds-shadow-border-large);
  --shadow-tooltip: var(--ds-shadow-tooltip);
  --shadow-menu: var(--ds-shadow-menu);
  --shadow-modal: var(--ds-shadow-modal);
  --shadow-fullscreen: var(--ds-shadow-fullscreen);
  --ease-swift: var(--fc-ease-swift);
}

/* Semantic Facet colors as utilities: bg-fc-surface-subtle, text-fc-signal-go-fg ... */
@theme inline {
  ${semLight.map((l) => l.replace(/^--fc-([^:]+):.*$/, '--color-fc-$1: var(--fc-$1);')).filter((l) => l.startsWith('--color-fc-text') || l.startsWith('--color-fc-surface') || l.startsWith('--color-fc-border') || l.startsWith('--color-fc-status') || l.startsWith('--color-fc-signal') || l.startsWith('--color-fc-edge') || l.startsWith('--color-fc-gem') || l.startsWith('--color-fc-freshness') || l.startsWith('--color-fc-chart')).join('\n  ')}
}

@custom-variant dark (&:where(.dark-theme, .dark-theme *, [data-theme="dark"], [data-theme="dark"] *));

${twUtil.join('\n')}

@utility tabular {
  font-variant-numeric: tabular-nums;
}
`;
write('css/tailwind.css', tw);

// ---------- js/tokens.mjs (resolved values for canvas/SVG charts) ----------
const resolved = { light: {}, dark: {} };
for (const [scale, steps] of Object.entries(prim.color)) {
  for (const [step, t] of Object.entries(steps)) {
    resolved.light[`${scale}-${step}`] = t.$value;
    resolved.dark[`${scale}-${step}`] = ext(t).dark || t.$value;
  }
}
const semResolved = { light: {}, dark: {} };
(function walk(node, path) {
  for (const [k, v] of Object.entries(node)) {
    if (k.startsWith('$')) continue;
    const p = [...path, k];
    if (isTok(v)) {
      const key = p.join('-');
      const pick = (val, mode) => String(val).replace(/\{color\.([a-z-]+)\.(\d+)\}/, (_, s, n) => resolved[mode][`${s}-${n}`]);
      semResolved.light[key] = pick(v.$value, 'light');
      semResolved.dark[key] = pick(ext(v).dark || v.$value, 'dark');
    } else if (v && typeof v === 'object') walk(v, p);
  }
})(sem, []);
const js = `// GENERATED by packages/facet/scripts/build.mjs. Do not edit by hand.
// Resolved sRGB values for places CSS variables cannot reach (canvas charts, OG images, emails).
// In the DOM prefer var(--fc-*) / var(--ds-*), which also pick up P3 and theme changes.
export const primitives = ${JSON.stringify(resolved, null, 2)};
export const semantic = ${JSON.stringify(semResolved, null, 2)};
export const typography = ${JSON.stringify(Object.fromEntries(Object.entries(type).map(([k, t]) => [k, t.$value])), null, 2)};
export function token(name, mode = 'light') {
  return semantic[mode][name] ?? primitives[mode][name];
}
`;
write('js/tokens.mjs', js);

// ---------- preview/semantic-map.js (lets the specimen draw which semantic token uses which step) ----------
const aliasMap = { light: {}, dark: {} };
(function walk(node, path) {
  for (const [k, v] of Object.entries(node)) {
    if (k.startsWith('$')) continue;
    const p = [...path, k];
    if (isTok(v)) {
      const ref = (x) => { const m = String(x).match(/\{color\.([a-z-]+)\.(\d+)\}/); return m ? `${m[1]}-${m[2]}` : null; };
      aliasMap.light[p.join('-')] = ref(v.$value);
      aliasMap.dark[p.join('-')] = ref(ext(v).dark || v.$value);
    } else if (v && typeof v === 'object') walk(v, p);
  }
})(sem, []);
write('preview/semantic-map.js', `// GENERATED by packages/facet/scripts/build.mjs. Do not edit by hand.\nwindow.FACET_ALIASES = ${JSON.stringify(aliasMap)};\n`);
